import { createMayarin } from "@mayarin/sdk";

const secretKey = process.env.MAYARIN_SECRET_KEY;
if (!secretKey) throw new Error("MAYARIN_SECRET_KEY is required");

const mayarin = createMayarin({
  baseUrl: "https://api.mayarin.xyz",
  secretKey,
});

// Priced in the currency the business already uses. Amounts are
// human-readable decimal strings — never a float.
const link = await mayarin.commerce.paymentLinks.create({
  kind: "fixed",
  merchant: {
    id: "M-1",
    name: "Studio Supply",
    city: "Jakarta",
    countryCode: "ID",
  },
  amount: { amount: "1500000.00", asset: "IDR" },
  title: "Brand design package",
  merchantReference: "inv-2026-014",
});

// Share it. Nothing about a chain has been decided yet.
console.log(link.url);

// Every (chain, asset) pair this link can be paid on — the same list the
// hosted checkout renders, derived the same way.
const { rails, settlementAsset } = await mayarin.commerce.paymentLinks.rails(
  link.id,
);

for (const rail of rails) {
  console.log(`${rail.asset} on ${rail.chain} settles as ${settlementAsset}`);
}
// USDC on base settles as USDC
// EURC on base settles as USDC
// USDC on arc  settles as USDC

// The payer picks one. The quote layer prices the pair against an oracle
// reference and refuses the trade if the venue has drifted too far from it.
const intent = await mayarin.commerce.paymentLinks.checkout(link.id, {
  payment: { asset: "EURC", chain: "base" },
});

console.log(intent.state); // "PRICE_LOCKED"

import { constructWebhook } from "@mayarin/sdk";

const webhookSecret = process.env.MAYARIN_WEBHOOK_SECRET;
if (!webhookSecret) throw new Error("MAYARIN_WEBHOOK_SECRET is required");

type PaymentEvent = {
  readonly type: "payment.created" | "payment.state_changed" | "payment.failed";
  readonly state: string;
  readonly clearingTransactionId: string;
};

export async function POST(request: Request) {
  // A webhook is a signal, not truth: the signature is checked, then the
  // authoritative state is read back from the API.
  const event = await constructWebhook<PaymentEvent>({
    payload: await request.text(),
    signature: request.headers.get("Mayarin-Signature") ?? "",
    secret: webhookSecret,
  });

  if (event.type !== "payment.state_changed") return new Response(null, { status: 204 });

  const payment = await mayarin.payment.get(event.clearingTransactionId);
  if (payment.state === "SETTLED") await markOrderPaid(payment.merchantReference);

  return new Response(null, { status: 204 });
}
